def sim(plant_d1=True, plant_d2=True, thresh=0.99, seed=0):
    rng = random.Random(seed)
    decoy = rng.randrange(40)
    mole = rng.choice([i for i in range(40) if i != decoy])

    V = 1.0
    docs = []
    leaked_ids = set()
    scheduled_leaks = []
    probs = [1.0/40]*40
    rot = 0

    for day in range(1, 22):
        if day == 1:
            d1_pairs = [("Eng","Fin"), ("Fin","Res"), ("Leg","Res"), ("Eng","Res")]
            for idx, (a, b) in enumerate(d1_pairs):
                rec = {i for i in range(40) if emp_dept[i] in (a, b)}
                docs.append((f"d1-{idx}", 1, rec, False, None))
        else:
            nd = rng.choice([2, 3, 4])
            for idx in range(nd):
                a, b = rng.sample(dept_names, 2)
                rec = {i for i in range(40) if emp_dept[i] in (a, b)}
                docs.append((f"d{day}-{idx}", day, rec, False, None))

        actions = 8
        if day >= 2:
            probs[decoy] = 0.0
            actions -= 1
