                if i == decoy or probs[i] == 0.0: continue
                ah = pois(rng, 0.30 if i == mole else 0.1263)
                nm = pois(rng, 0.70 if i == mole else 0.90)
                probs[i] *= ((0.30**ah)*math.exp(-0.30)*((0.70**nm)*math.exp(-0.70))) / (
                            ((0.1263**ah)*math.exp(-0.1263)*((0.90**nm)*math.exp(-0.90))))
        if day == 2:
            actions -= 1

        if day >= 3:
            actions -= 1
            for s_day, doc_id, shown_var in scheduled_leaks:
                if s_day == day:
                    doc = [x for x in docs if x[0] == doc_id][0]
                    _, _, rec, is_c, vmap = doc
                    for i in range(40):
                        if i not in rec:
                            probs[i] = 0.0
                        elif is_c:
                            n_vars = len(set(vmap.values()))
                            if vmap[i] == shown_var:
                                probs[i] *= 0.95
                            else:
                                probs[i] *= 0.05 / max(1, n_vars - 1)

        tot = sum(probs)
        probs = [p/tot for p in probs]
        best_i = max(range(40), key=lambda i: probs[i])
        if probs[best_i] >= thresh or (day == 21 and probs[best_i] > 1.0/(1.0 + max(0.1, V))):
            return V if best_i == mole else -1.0, day, best_i == mole

        # Alive candidates (non-zero prob)
        alive = [i for i in range(40) if probs[i] > 0.0]
        alive.sort(key=lambda i: -probs[i])
        elim = [i for i in range(40) if probs[i] == 0.0 and i != decoy]
        if not elim and decoy is not None and day >= 2:
            elim = [decoy]

        def make_canary(target_list, cid):
            nonlocal V, actions
            vmap = {}
            # Assign target_list across A, B (and C if len >= 3); if len <= 2, put padding in C!
            if len(target_list) == 1:
                vmap[target_list[0]] = "A"
                for p_i, e in enumerate(elim[:3]):
                    vmap[e] = "B" if p_i == 0 else "C"
            elif len(target_list) == 2:
                vmap[target_list[0]] = "A"
                vmap[target_list[1]] = "B"
                for e in elim[:2]:
                    vmap[e] = "C"
            elif len(target_list) == 3:
                vmap[target_list[0]] = "A"
                vmap[target_list[1]] = "B"
                vmap[target_list[2]] = "C"
                if elim:
                    vmap[elim[0]] = "C"
            else:
                for idx, emp in enumerate(target_list):
                    vmap[emp] = ["A", "B", "C"][idx % 3]
            docs.append((cid, day, set(vmap.keys()), True, vmap))
            V -= 0.01
            actions -= 1

        if day == 1 and plant_d1:
            c1, c2 = [], []
            for d in ["Eng", "Fin", "Leg", "Res"]:
                emps = [i for i in range(40) if emp_dept[i] == d]
                mid = len(emps)//2
                c1.extend(emps[:mid])
                c2.extend(emps[mid:])
            make_canary(c1, "c1-1")
            make_canary(c2, "c1-2")
        elif day == 2 and plant_d2:
            # Cross-dept orthogonal split including Sales (minus decoy)!
            c1, c2 = [], []
            for d in dept_names:
                emps = [i for i in range(40) if emp_dept[i] == d and i != decoy]
                c1.extend(emps[0::2])
                c2.extend(emps[1::2])
            make_canary(c1, "c2-1")
            make_canary(c2, "c2-2")
        elif day >= 3 and len(alive) >= 2 and len(alive) <= 24:
            # Focus on high-mass candidates (covering >= 99.5% mass)
            top = []
            cum = 0.0
            for x in alive:
                top.append(x)
                cum += probs[x]
                if cum >= 0.995 and len(top) >= 2:
                    break
            if len(top) == 2:
                # 1-candidate exact-isolation canaries!!
                make_canary([top[0]], f"c{day}-1")
                make_canary([top[1]], f"c{day}-2")
            else:
                # Orthogonal binary split + 3-way variant = 6-way split per day!
                if probs[top[0]] >= 0.55 and len(top) <= 8:
                    # Isolate #1 suspect in Canary 1, put rest in Canary 2!
                    make_canary([top[0]], f"c{day}-1")
                    make_canary(top[1:], f"c{day}-2")
                else:
                    # Rotate split each day so consecutive days are orthogonal!
                    if rot % 3 == 0:
                        g1, g2 = top[0::2], top[1::2]
                    elif rot % 3 == 1:
                        mid = len(top)//2
                        g1, g2 = top[:mid], top[mid:]
                    else:
                        g1 = [top[i] for i in range(len(top)) if (i // 2) % 2 == 0]
                        g2 = [top[i] for i in range(len(top)) if (i // 2) % 2 == 1]
                    rot += 1
                    make_canary(g1, f"c{day}-1")
                    if g2:
                        make_canary(g2, f"c{day}-2")

        # Leftover actions -> interview top suspects (4 topics each)
        for emp in alive:
            for _ in range(4):
                if actions <= 0: break
                actions -= 1
                p_ev = 0.24 if emp == mole else 0.20
                if rng.random() < p_ev:
                    probs[emp] *= (0.24 / 0.20)
                else:
                    probs[emp] *= (0.76 / 0.80)
            if actions <= 0: break

        tot = sum(probs)
        probs = [p/tot for p in probs]
        best_i = max(range(40), key=lambda i: probs[i])
        if probs[best_i] >= thresh:
            return V if best_i == mole else -1.0, day, best_i == mole

        elig = [d for d in docs if (day - d[1] <= 2) and (mole in d[2]) and (d[0] not in leaked_ids)]
        if elig and rng.random() < 0.65:
            weights = [1.0 if not d[3] else (1.0 - len(d[2])/40.0) for d in elig]
            if sum(weights) > 0:
                picked = rng.choices(elig, weights=weights, k=1)[0]
                leaked_ids.add(picked[0])
                V = max(0.0, V - 0.05)
                delay = rng.choice([2, 3])
                shown_var = None
                if picked[3]:
                    true_var = picked[4][mole]
                    all_vars = list(set(picked[4].values()))
                    if rng.random() < 0.95 or len(all_vars) == 1:
                        shown_var = true_var
                    else:
                        shown_var = rng.choice([v for v in all_vars if v != true_var])
                scheduled_leaks.append((day + delay, picked[0], shown_var))
    return 0.0, 21, False

for p1, p2 in [(False, False), (True, False), (False, True), (True, True)]:
    for th in [0.98, 0.99]:
        scores, days, wins = [], [], 0
        N = 4000
        for s in range(N):
            sc, dy, w = sim(p1, p2, th, s)
            scores.append(sc)
            days.append(dy)
            wins += int(w)
